import { Cover, TemplateSlide } from 'components';
import DOMPurify from 'dompurify';
import { PORTFOLIOS_TYPES } from 'pages/constants';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import {
  StyledContent,
  StyledParagraph,
} from '../../../BrandPowerBookExport.styles';
import {
  EXECUTIVE_SUMMARY_INSIGHTS_CONFIG,
  GLOBAL_FOOTNOTES,
  UNIFIED_GLOBAL_SLIDES,
} from '../../../constants';
import { findInsightTexts } from '../../../helpers';
import { buildGlobalDataForPeriod } from '../../../hooks/usePowerBookGlobalData/usePowerBookGlobalData';
import type {
  ByCountryConfig,
  ContributionConfig,
  CoverConfig,
  EvolutionConfig,
  ExecutiveSummaryConfig,
  InsightRecord,
  PerformanceConfig,
  UnifiedSlideConfig,
} from '../../../types';
import { ByCountrySlide } from '../../ByCountrySlide';
import { EvolutionSlideWrapper } from '../../EvolutionSlideWrapper';
import { GenericPerformanceSlide } from '../../GenericPerformanceSlide';
import { InsightsSlide } from '../../InsightsSlide';
import { TopCountryContribution } from '../../TopContribuitionCountry';

type GlobalPeriodData = ReturnType<typeof buildGlobalDataForPeriod>;

export interface SlideRenderContext {
  globalData: GlobalPeriodData;
  sectionSuffix: string;
  period: string;
  coverPeriod: React.ReactNode;
  getPageByName: (name: string) => { index: number } | undefined;
  formatMessage: (descriptor: { id: string }) => string;
  selectedPeriodType: 'QTD' | 'YTD';
  insights: InsightRecord[];
}

const renderEvolution = (config: EvolutionConfig, ctx: SlideRenderContext) => {
  const category = ctx.globalData[config.dataKey];
  const evolutionData = ctx.globalData.trendPowerEvolutionData[config.dataKey];

  return (
    <EvolutionSlideWrapper
      key={config.section}
      section={config.section}
      title={config.title}
      period={ctx.period}
      pageIndex={ctx.getPageByName(config.section)?.index}
      data={evolutionData}
      loading={!category}
      error={null}
      portfolioType={config.portfolioType as keyof typeof PORTFOLIOS_TYPES}
      alerts={findInsightTexts(ctx.insights, {
        ...config.insight,
        timeframe: ctx.selectedPeriodType,
      })}
    />
  );
};

const renderByCountry = (config: ByCountryConfig, ctx: SlideRenderContext) => {
  const section = `${config.section}${ctx.sectionSuffix}`;
  const category = ctx.globalData[config.dataKey];

  return (
    <StyledExportPageSection key={section} data-page-name={section}>
      <TemplateSlide
        enablePngCopy
        title={config.title}
        period={ctx.period}
        footnotes={GLOBAL_FOOTNOTES}
        page={ctx.getPageByName(section)?.index}
        countryId="ABI"
        headerDivider={false}
        dataTestId={section}
      >
        <StyledContent>
          <ByCountrySlide
            loading={!category}
            error={null}
            bigNumbersData={category?.bigNumbers}
            zoneKpiData={category?.zonePerformance?.zonePowerPerformance}
            nazKpiData={category?.zonePerformanceDetails?.NAZ}
            sazKpiData={category?.zonePerformanceDetails?.SAZ}
            mazKpiData={category?.zonePerformanceDetails?.MAZ}
            apacKpiData={category?.zonePerformanceDetails?.APAC}
            afrKpiData={category?.zonePerformanceDetails?.AFR}
            eurKpiData={category?.zonePerformanceDetails?.EUR}
            alerts={findInsightTexts(ctx.insights, {
              ...config.insight,
              timeframe: ctx.selectedPeriodType,
            })}
            dataTestId={`slide-${section}`}
            selectedPeriodType={ctx.selectedPeriodType}
          />
        </StyledContent>
      </TemplateSlide>
    </StyledExportPageSection>
  );
};

const renderPerformance = (
  config: PerformanceConfig,
  ctx: SlideRenderContext,
) => {
  const section = `${config.section}${ctx.sectionSuffix}`;
  const category = ctx.globalData[config.dataKey];

  return (
    <GenericPerformanceSlide
      key={section}
      pageName={section}
      title={config.title}
      period={ctx.period}
      footnotes={GLOBAL_FOOTNOTES}
      pageIndex={ctx.getPageByName(section)?.index}
      loading={!category}
      error={null}
      data={category}
      alerts={findInsightTexts(ctx.insights, {
        ...config.insight,
        timeframe: ctx.selectedPeriodType,
      })}
      isCompetitor={config.isCompetitor}
      selectedPeriodType={ctx.selectedPeriodType}
    />
  );
};

const renderContribution = (
  config: ContributionConfig,
  ctx: SlideRenderContext,
) => {
  const section = `${config.section}${ctx.sectionSuffix}`;
  const allCategory = ctx.globalData.global;
  const megabrandsCategory = ctx.globalData.megabrands;

  return (
    <StyledExportPageSection key={section} data-page-name={section}>
      <TemplateSlide
        enablePngCopy
        title={config.title}
        period={ctx.period}
        footnotes={GLOBAL_FOOTNOTES}
        page={ctx.getPageByName(section)?.index}
        countryId="ABI"
        headerDivider={false}
        dataTestId={section}
      >
        <StyledContent
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: '15px',
          }}
        >
          <TopCountryContribution
            countryContribuitionKpiData={ctx.globalData.contribution?.global}
            loading={!allCategory}
            error={null}
            title={ctx.formatMessage({
              id: 'PortfolioBrand.BrandPowerBook.PowerBook.TopCountryContribution.titleTotalAbi',
            })}
            dataTestId="chart-country-contribution-abi"
          />
          <TopCountryContribution
            countryContribuitionKpiData={
              ctx.globalData.contribution?.megabrands
            }
            loading={!megabrandsCategory}
            error={null}
            title={ctx.formatMessage({
              id: 'PortfolioBrand.BrandPowerBook.PowerBook.TopCountryContribution.titleMegaBrands',
            })}
            dataTestId="chart-country-contribution-megabrands"
          />
        </StyledContent>
      </TemplateSlide>
    </StyledExportPageSection>
  );
};

const renderCover = (config: CoverConfig, ctx: SlideRenderContext) => {
  const section = `${config.section}${ctx.sectionSuffix}`;

  return (
    <StyledExportPageSection key={section} data-page-name={section}>
      <Cover
        category={config.category}
        name={config.name}
        loading={false}
        period={ctx.coverPeriod}
        showLogo
      />
    </StyledExportPageSection>
  );
};

const renderExecutiveSummary = (
  config: ExecutiveSummaryConfig,
  ctx: SlideRenderContext,
) => {
  const insights = ctx.insights
    ?.filter(
      (insight) =>
        insight.type === config.insight?.type &&
        insight.template === config.insight?.template &&
        !!insight.insight_text &&
        insight.insights_title !== 'None' &&
        insight.timeframe === ctx.selectedPeriodType,
    )
    .sort(
      (a, b) =>
        EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[a.insights_title].indexBadge -
        EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[b.insights_title].indexBadge,
    );

  if (!insights || insights.length === 0) {
    return null;
  }

  return (
    <StyledExportPageSection
      key={config.section}
      data-page-name={config.section}
    >
      <TemplateSlide
        enablePngCopy
        title={config.title}
        period={ctx.period}
        page={ctx.getPageByName(config.section)?.index}
        countryId="ABI"
        headerDivider={false}
        dataTestId={config.section}
      >
        <StyledContent $hasSpacing>
          {insights.map(
            (insight) =>
              !!insight.insight_text && (
                <InsightsSlide
                  key={insight.insights_title}
                  title={
                    EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[insight.insights_title]
                      .title
                  }
                  content={(insight.insight_text.split('\n') ?? []).map(
                    (alert, index) => (
                      <StyledParagraph
                        key={alert + index}
                        dangerouslySetInnerHTML={{
                          __html: DOMPurify.sanitize(alert),
                        }}
                      />
                    ),
                  )}
                  indexBadge={
                    EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[insight.insights_title]
                      .indexBadge
                  }
                />
              ),
          )}
        </StyledContent>
      </TemplateSlide>
    </StyledExportPageSection>
  );
};

export function renderSlideByType(
  config: UnifiedSlideConfig,
  ctx: SlideRenderContext,
): JSX.Element {
  switch (config.type) {
    case 'executive-summary':
      return renderExecutiveSummary(config, ctx);
    case 'evolution':
      return renderEvolution(config, ctx);
    case 'by-country':
      return renderByCountry(config, ctx);
    case 'performance':
      return renderPerformance(config, ctx);
    case 'contribution':
      return renderContribution(config, ctx);
    case 'cover':
      return renderCover(config, ctx);
  }
}

export const getSlideId = (
  config: (typeof UNIFIED_GLOBAL_SLIDES)[number],
  sectionSuffix: string,
): string => {
  switch (config.type) {
    case 'by-country':
    case 'performance':
    case 'cover':
    case 'contribution':
      return `${config.section}${sectionSuffix}`;
    default:
      return config.section;
  }
};
